/* ============================================
   PROGRESS BAR COMPONENT
   Displays completion progress as a horizontal bar
   ============================================ */

.ds-progress-bar {
  display: flex;
  align-items: center;
  gap: var(--padding-200);
  width: 100%;
}

/* ============================================
   TRACK
   ============================================ */

.ds-progress-bar__track {
  flex: 1;
  height: 8px;
  background-color: var(--color-bg-container-tertiary);
  border-radius: var(--radius-pill);
  overflow: hidden;
}

.ds-progress-bar--compact .ds-progress-bar__track {
  height: 4px;
}

/* ============================================
   FILL
   ============================================ */

.ds-progress-bar__fill {
  height: 100%;
  border-radius: var(--radius-pill);
  transition: width var(--motion-duration-slow) var(--motion-ease-standard);
}

/* ============================================
   LABEL
   ============================================ */

.ds-progress-bar__label {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  min-width: 36px;
  text-align: right;
}

/* ============================================
   FILL COLOUR
   ============================================ */

.ds-progress-bar__fill {
  background-color: var(--color-core-accent-mint);
}

import './ProgressBar.css';

export interface ProgressBarProps {
  /** Current progress value (0–100) */
  value?: number;
  /** Size of the bar */
  size?: 'default' | 'compact';
  /** Show percentage label */
  showLabel?: boolean;
  /** Accessible label describing what is loading */
  ariaLabel?: string;
  /** Additional CSS classes */
  className?: string;
}

/**
 * ProgressBar displays completion progress as a horizontal bar.
 */
export const ProgressBar = ({
  value = 0,
  size = 'default',
  showLabel = false,
  ariaLabel,
  className = '',
}: ProgressBarProps) => {
  const clamped = Math.max(0, Math.min(100, value));
  const baseClass = 'ds-progress-bar';
  const classes = [
    baseClass,
    `${baseClass}--${size}`,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <div className={classes} role="progressbar" aria-valuenow={clamped} aria-valuemin={0} aria-valuemax={100} aria-label={ariaLabel || 'Progress'}>
      <div className={`${baseClass}__track`}>
        <div className={`${baseClass}__fill`} style={{ width: `${clamped}%` }} />
      </div>
      {showLabel && <span className={`${baseClass}__label`}>{clamped}%</span>}
    </div>
  );
};
